import base64, os, subprocess

print("==================================================")
print("🚀 正在自動生成並寫入卡片高清圖片 ...")
print("==================================================")

os.makedirs("frontend/public", exist_ok=True)

# 1. 自動寫入 A.I. 算命與預約丁蔓山兩張圖片至 frontend/public/
with open("frontend/public/ai_card_img.jpg", "wb") as f:
    f.write(base64.b64decode(""""""))

with open("frontend/public/booking_card_img.jpg", "wb") as f:
    f.write(base64.b64decode(""""""))

print("✓ [1/3] frontend/public/ai_card_img.jpg 寫入成功！")
print("✓ [1/3] frontend/public/booking_card_img.jpg 寫入成功！")

# 2. 復原 ThreeCoreProducts.tsx 中標準圖片引用
comp_path = "frontend/src/components/ThreeCoreProducts.tsx"
if os.path.exists(comp_path):
    with open(comp_path, "r", encoding="utf-8") as f:
        code = f.read()
    
    code = code.replace('onError={(e)=>{ (e.target as HTMLElement).style.display="none"; }}', '')
    
    with open(comp_path, "w", encoding="utf-8") as f:
        f.write(code)
    print("✓ [2/3] ThreeCoreProducts.tsx 圖片渲染已復原！")

# 3. 執行 Vite 打包編譯
print(">>> [3/3] 正在執行 Vite 打包編譯 ...")
subprocess.run("cd frontend && npm run build", shell=True, check=True)
print("==================================================")
print("🎉 圖片部署成功！請執行 git commit & push 更新站點。")
print("==================================================")
